struct bio *iov_iter_to_bio(struct request_queue *q, const struct iov_iter *iter, gfp_t gfp_mask) {
    unsigned int nr_pages = iov_iter_npages(iter, INT_MAX);
    struct bio *bio;
    struct page **pages;
    size_t iter_len = iov_iter_count(iter);
    size_t total_bytes = 0;
    size_t offset = 0;
    int i = 0;

    if (!nr_pages)
        return ERR_PTR(-EINVAL);

    pages = kmalloc_array(nr_pages, sizeof(struct page *), gfp_mask);
    if (!pages)
        return ERR_PTR(-ENOMEM);

    nr_pages = iov_iter_get_pages(iter, pages, INT_MAX, nr_pages, &offset);
    if (!nr_pages) {
        kfree(pages);
        return ERR_PTR(-EFAULT);
    }

    bio = bio_alloc(GFP_KERNEL, nr_pages);
    if (!bio) {
        iov_iter_revert(iter, iov_iter_count(iter) - iter_len);
        kfree(pages);
        return ERR_PTR(-ENOMEM);
    }

    for (i = 0; i < nr_pages; i++) {
        struct bio_vec bv;
        size_t len = min_t(size_t, iter_len - total_bytes, PAGE_SIZE - offset);

        bv.bv_page = pages[i];
        bv.bv_len = len;
        bv.bv_offset = offset;

        bio_add_page(bio, bv.bv_page, bv.bv_len, bv.bv_offset);
        total_bytes += bv.bv_len;
        offset = 0;
    }

    bio->bi_flags |= BIO_USER_MAPPED;
    kfree(pages);

    return bio;
}

struct bio *bio_map_user_iov(struct request_queue *q, const struct iov_iter *iter, gfp_t gfp_mask)
{
    struct bio *bio = NULL;
    struct bio_vec *bvec = NULL;
    struct page **pages = NULL;
    unsigned int nr_vecs = iov_iter_npages(iter, BIO_MAX_PAGES);
    size_t nr_segs;
    ssize_t ret;

    if (nr_vecs == 0)
        return ERR_PTR(-EFAULT);

    bio = bio_alloc(gfp_mask, nr_vecs);
    if (!bio)
        return ERR_PTR(-ENOMEM);

    pages = kmalloc_array(nr_vecs, sizeof(struct page *), gfp_mask);
    if (!pages) {
        ret = -ENOMEM;
        goto err_out;
    }

    bvec = bio->bi_io_vec;
    nr_segs = 0;

    while (iov_iter_count(iter)) {
        struct page *page;
        size_t len;

        ret = iov_iter_get_pages(iter, &page, PAGE_SIZE, 1, &len);
        if (ret <= 0) {
            if (!ret)
                ret = -EFAULT;
            goto unmap;
        }

        pages[nr_segs] = page;
        bvec[nr_segs].bv_page = page;
        bvec[nr_segs].bv_len = len;
        bvec[nr_segs].bv_offset = 0;

        iov_iter_advance(iter, len);
        nr_segs++;
    }

    bio_set_pages(bio, pages, nr_segs);
    bio->bi_flags |= BIO_USER_MAPPED;

    return bio;

unmap:
    while (nr_segs--)
        put_page(pages[nr_segs]);
    kfree(pages);
err_out:
    bio_put(bio);
    return ERR_PTR(ret);
}

struct bio *bio_map_user_iov(struct request_queue *q, const struct iov_iter *iter, gfp_t gfp_mask) {
    struct bio *bio;
    struct page **pages;
    size_t nr_pages, i;
    unsigned int nr_segs;
    int ret;

    bio = bio_alloc(gfp_mask, 0);
    if (!bio)
        return ERR_PTR(-ENOMEM);

    iov_iter_init(iter, 0);
    nr_pages = iov_iter_npages(iter, BIO_MAX_PAGES);
    if (!nr_pages) {
        ret = -EFAULT;
        goto err_bio;
    }

    pages = kmalloc_array(nr_pages, sizeof(struct page *), gfp_mask);
    if (!pages) {
        ret = -ENOMEM;
        goto err_bio;
    }

    nr_segs = iov_iter_get_pages_alloc(iter, pages, nr_pages, &bio->bi_vcnt);
    if (nr_segs <= 0) {
        ret = nr_segs ? nr_segs : -EFAULT;
        goto err_pages;
    }

    for (i = 0; i < bio->bi_vcnt; i++) {
        struct page *page = pages[i];
        int offset = (unsigned long)iov_iter_iov(iter, i)->iov_base & (PAGE_SIZE - 1);
        int len = iov_iter_iov(iter, i)->iov_len;

        if (offset + len > PAGE_SIZE) {
            ret = -EINVAL;
            goto err_unmap;
        }

        bio_add_page(bio, page, len, offset);
    }

    bio->bi_flags |= (1 << BIO_USER_MAPPED);

    kfree(pages);
    return bio;

err_unmap:
    for (i = 0; i < bio->bi_vcnt; i++)
        put_page(pages[i]);
    kfree(pages);
err_pages:
    kfree(pages);
err_bio:
    bio_put(bio);
    return ERR_PTR(ret);
}

struct bio *bio_map_user_iov(struct request_queue *q, const struct iov_iter *iter, gfp_t gfp_mask)
{
    struct bio *bio;
    unsigned long nr_pages = 1;
    struct page **pages;
    size_t off, len;
    int ret;

    while (iov_iter_get_pages(iter, pages, NULL, 0, &len)) {
        nr_pages++;
    }

    bio = bio_kmalloc(gfp_mask, nr_pages);
    if (!bio)
        return ERR_PTR(-ENOMEM);

    pages = kmalloc_array(nr_pages, sizeof(struct page *), gfp_mask);
    if (!pages) {
        bio_put(bio);
        return ERR_PTR(-ENOMEM);
    }

    iov_iter_get_pages_alloc(iter, &pages, &len, nr_pages, &off);
    if (!len) {
        kfree(pages);
        bio_put(bio);
        return ERR_PTR(-EFAULT);
    }

    bio->bi_vcnt = 0;
    for (unsigned int i = 0; i < nr_pages; i++) {
        struct bio_vec bv;

        bv.bv_page = pages[i];
        bv.bv_len = min(len, (size_t)(PAGE_SIZE - off));
        bv.bv_offset = off;
        len -= bv.bv_len;
        off = 0;
        ret = bio_add_vec(bio, &bv);
        if (ret != bv.bv_len) {
            kfree(pages);
            bio_put(bio);
            return ERR_PTR(-EFAULT);
        }
    }

    bio->bi_flags |= (1 << BIO_USER_MAPPED);
    return bio;
}

struct bio *bio_map_user_iov(struct request_queue *q, const struct iov_iter *iter, gfp_t gfp_mask) {
    struct bio *bio;
    struct page **pages;
    size_t nr_pages = 0;
    size_t nr_mapped = 0;
    size_t total_len = iov_iter_count(iter);
    ssize_t ret;
    struct iov_iter i = *iter;

    if (!iov_iter_count(&i))
        return ERR_PTR(-EINVAL);

    while (iov_iter_count(&i)) {
        struct iovec iov;
        ssize_t len;

        if (!iov_iter_next(&i, &iov, &len))
            continue;

        size_t page_start = offset_in_page(iov.iov_base);
        size_t page_len = (iov.iov_len + page_start + PAGE_SIZE - 1) & ~(PAGE_SIZE - 1);
        nr_pages += page_len >> PAGE_SHIFT;
    }

    bio = bio_alloc(gfp_mask, nr_pages);
    if (!bio)
        return ERR_PTR(-ENOMEM);

    pages = kmalloc_array(nr_pages, sizeof(struct page *), gfp_mask);
    if (!pages) {
        bio_put(bio);
        return ERR_PTR(-ENOMEM);
    }

    iov_iter_init(&i, i.direction, i iov, i iov_count, i iov_index, i iov_offset);

    while (iov_iter_count(&i)) {
        struct page *page;
        unsigned long offset;
        size_t size;

        ret = iov_iter_get_pages(&i, pages + nr_mapped, iov_iter_count(&i), nr_pages - nr_mapped, &size);
        if (ret < 0)
            goto cleanup;

        for (unsigned int j = 0; j < ret; j++) {
            page = pages[nr_mapped + j];
            offset = offset_in_page(i iov_base);
            bio_add_page(bio, page, size, offset);
        }

        nr_mapped += ret;
        iov_iter_advance(&i, ret * PAGE_SIZE);
    }

    if (bio->bi_iter.bi_size != total_len)
        goto cleanup;

    bio->bi_flags |= BIO_USER_MAPPED;
    return bio;

cleanup:
    for (unsigned int j = 0; j < nr_mapped; j++)
        put_page(pages[j]);

    kfree(pages);
    bio_put(bio);
    return ERR_PTR(-EFAULT);
}
